CREATE TABLE tenant (\n  tenant_id  uuid PRIMARY KEY,\n  name       varchar(200) NOT NULL,\n  active     boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nINSERT INTO tenant VALUES ('00000000-0000-0000-0000-000000000001',\n                           'default', true, now());\n\nCREATE TABLE project (\n  tenant_id   uuid NOT NULL,\n  project_id  uuid NOT NULL,\n  name        varchar(200) NOT NULL,\n  timezone    varchar(60) NOT NULL,\n  status      varchar(30) NOT NULL,\n  start_date  date,\n  end_date    date,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, project_id)\n);\n\nCREATE TABLE party (\n  tenant_id  uuid NOT NULL,\n  party_id   uuid NOT NULL,\n  legal_name varchar(300) NOT NULL,\n  tax_id     varchar(50),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, party_id)\n);\n\nCREATE TABLE party_role (\n  tenant_id  uuid NOT NULL,\n  party_id   uuid NOT NULL,\n  role       varchar(50) NOT NULL,\n  valid_from timestamptz NOT NULL DEFAULT now(),\n  valid_to   timestamptz,\n  PRIMARY KEY (tenant_id, party_id, role, valid_from)\n);\n\nCREATE TABLE site (\n  tenant_id    uuid NOT NULL,\n  site_id      uuid NOT NULL,\n  project_id   uuid NOT NULL,\n  jurisdiction varchar(40) NOT NULL,\n  coordinates  point,\n  PRIMARY KEY (tenant_id, site_id)\n);\n\nCREATE TABLE contract (\n  tenant_id      uuid NOT NULL,\n  contract_id    uuid NOT NULL,\n  project_id     uuid NOT NULL,\n  amount         numeric(18,2) NOT NULL,\n  currency       char(3) NOT NULL,\n  contract_type  varchar(40) NOT NULL,\n  effective_from date NOT NULL,\n  effective_to   date,\n  PRIMARY KEY (tenant_id, contract_id)\n);\n\nCREATE TABLE contract_party (\n  tenant_id        uuid NOT NULL,\n  contract_id      uuid NOT NULL,\n  party_id         uuid NOT NULL,\n  role_in_contract varchar(40) NOT NULL,\n  PRIMARY KEY (tenant_id, contract_id, party_id)\n);\n\nCREATE TABLE work_package (\n  tenant_id       uuid NOT NULL,\n  work_package_id uuid NOT NULL,\n  project_id      uuid NOT NULL,\n  contract_id     uuid NOT NULL,\n  discipline      varchar(80),\n  location        varchar(120),\n  PRIMARY KEY (tenant_id, work_package_id)\n);\n\nCREATE TABLE document (\n  tenant_id       uuid NOT NULL,\n  document_id     uuid NOT NULL,\n  project_id      uuid NOT NULL,\n  work_package_id uuid,\n  mime_type       varchar(100),\n  sha256          varchar(64) NOT NULL,\n  author_id       uuid,\n  version         int NOT NULL DEFAULT 1,\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, document_id)\n);\nCREATE INDEX idx_doc_project ON document (tenant_id, project_id);\n\nCREATE TABLE shared_kernel_party_map (\n  tenant_id     uuid NOT NULL,\n  legacy_system varchar(40) NOT NULL,\n  legacy_id     varchar(80) NOT NULL,\n  new_party_id  uuid NOT NULL,\n  merged_at     timestamptz NOT NULL DEFAULT now(),\n  merged_by     uuid NOT NULL,\n  PRIMARY KEY (tenant_id, legacy_system, legacy_id)\n);\n\n-- Audit con hash chain verificable\nCREATE TABLE audit_event (\n  tenant_id       uuid NOT NULL,\n  sequence_number bigserial NOT NULL,\n  event_id        uuid NOT NULL,\n  event_type      varchar(60) NOT NULL,\n  aggregate_type  varchar(40) NOT NULL,\n  aggregate_id    uuid NOT NULL,\n  actor_id        uuid,\n  correlation_id  uuid,\n  payload         jsonb NOT NULL,\n  prev_hash       varchar(64),\n  event_hash      varchar(64) NOT NULL,\n  recorded_at     timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, sequence_number)\n);\nCREATE INDEX idx_audit_aggregate ON audit_event (tenant_id, aggregate_type, aggregate_id);\n\nCREATE OR REPLACE FUNCTION compute_event_hash(p_prev varchar, p_payload jsonb)\nRETURNS varchar LANGUAGE sql IMMUTABLE AS $$\n  SELECT encode(\n    sha256(convert_to(coalesce(p_prev,'') || p_payload::text, 'UTF8')), 'hex');\n$$;\n\nCREATE OR REPLACE FUNCTION verify_audit_chain(p_tenant uuid)\nRETURNS TABLE(broken_at bigint) LANGUAGE sql STABLE AS $$\n  SELECT a.sequence_number FROM audit_event a\n    LEFT JOIN audit_event prev\n      ON prev.tenant_id = a.tenant_id\n     AND prev.sequence_number = a.sequence_number - 1\n   WHERE a.tenant_id = p_tenant\n     AND a.prev_hash IS DISTINCT FROM coalesce(prev.event_hash, '')\n   ORDER BY a.sequence_number;\n$$;